//! A-01 Architecture Clarity — integration tests for remaining force outcomes.

use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .expect("failed to run residual binary")
}

fn init(dir: &TempDir) {
    let out = run(dir, &["init"]);
    assert!(
        out.status.success(),
        "init failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
}

// S-26 / P-05: matrix show documents sticky header limits beside the action
#[test]
fn matrix_show_documents_sticky_viewport_limits() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "attractor",
            "--name",
            "X",
            "--description",
            "d",
            "--positive-state",
            "ok",
            "--negative-state",
            "bad",
        ],
    );
    run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "test",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "none",
            "--components",
            "auth",
        ],
    );
    let out = run(&dir, &["matrix", "show"]);
    assert!(
        out.status.success(),
        "matrix show failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        stderr.contains("sticky") || stderr.contains("--csv"),
        "expected viewport limit note on stderr, got:\n{stderr}"
    );
}

// P-16 / S-25: attractors must carry both positive and negative state pressure
#[test]
fn verify_links_catches_attractor_missing_dual_pressure() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    std::fs::write(
        dir.path().join("residual/attractors.csv"),
        "id,name,description,positive_state,negative_state\n\
         A-01,Clarity,desc,coherent,\n",
    )
    .unwrap();
    let out = run(&dir, &["verify", "links"]);
    assert!(
        !out.status.success(),
        "verify links should fail when negative_state is empty"
    );
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("negative_state") || stdout.contains("negative state"),
        "expected dual-pressure violation, got:\n{stdout}"
    );
}

// P-10: default walk expects stakeholder + direct-user personas (surfaced as warning)
#[test]
fn stressor_walk_context_warns_without_stakeholder_and_direct_user() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "persona",
            "--name",
            "solo",
            "--role",
            "Engineer",
            "--concerns",
            "none",
        ],
    );
    run(
        &dir,
        &[
            "add",
            "persona",
            "--name",
            "other",
            "--role",
            "Reviewer",
            "--concerns",
            "none",
        ],
    );
    let out = run(&dir, &["skill-data", "stressor-walk"]);
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("stakeholder") && stdout.contains("direct"),
        "expected stakeholder/direct-user persona note, got:\n{stdout}"
    );
}

#[test]
fn stressor_walk_context_ok_with_stakeholder_and_direct_user_personas() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "persona",
            "--name",
            "biz",
            "--role",
            "Stakeholder (Product Owner)",
            "--concerns",
            "cost",
        ],
    );
    run(
        &dir,
        &[
            "add",
            "persona",
            "--name",
            "user",
            "--role",
            "Direct User",
            "--concerns",
            "latency",
        ],
    );
    let out = run(&dir, &["skill-data", "stressor-walk"]);
    assert!(out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        !stdout.contains("Persona note"),
        "adequate personas should not warn, got:\n{stdout}"
    );
}

