/// Until longitudinal alpha/beta exist, walks/sessions require min:2 personas
/// including one stakeholder and one direct user (P-10).
pub fn check_personas_adequacy<S: AsRef<str>>(names: &[S]) -> Result<()> {
    if names.len() < 2 {
        bail!(
            "verification requires at least 2 personas (stakeholder + direct user) until alpha/beta exist; found {}",
            names.len()
        );
    }
    Ok(())
}

pub fn check_personas_roles(personas: &[crate::skills::personas::Persona]) -> Result<()> {
    if personas.len() < 2 {
        bail!(
            "requires at least 2 personas (stakeholder + direct user) until alpha/beta exist; found {}",
            personas.len()
        );
    }
    let has_stakeholder = personas.iter().any(|p| role_is_stakeholder(&p.role));
    let has_direct_user = personas.iter().any(|p| role_is_direct_user(&p.role));
    if !has_stakeholder || !has_direct_user {
        bail!(
            "requires one stakeholder persona and one direct-user persona until alpha/beta exist; \
             found roles: {}",
            personas
                .iter()
                .map(|p| format!("{} ({})", p.name, p.role))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    Ok(())
}

fn role_is_stakeholder(role: &str) -> bool {
    role.to_lowercase().contains("stakeholder")
}

fn role_is_direct_user(role: &str) -> bool {
    let r = role.to_lowercase();
    r.contains("direct user")
        || r.contains("direct-user")
        || r.contains("end user")
        || r.contains("end-user")
}

