    let has_stakeholder = personas
        .iter()
        .any(|p| p.role.to_lowercase().contains("stakeholder"));
    let has_direct_user = personas.iter().any(|p| {
        let r = p.role.to_lowercase();
        r.contains("direct user")
            || r.contains("direct-user")
            || r.contains("end user")
            || r.contains("end-user")
    });
    if !(has_stakeholder && has_direct_user) {
        bail!(
            "requires one stakeholder persona and one direct-user persona until alpha/beta exist; found roles: {}",
            personas
                .iter()
                .map(|p| format!("{} ({})", p.name, p.role))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    Ok(())
}

