use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .unwrap()
}

fn init(dir: &TempDir) {
    assert!(run(dir, &["init"]).status.success());
}

#[test]
fn matrix_show_documents_sticky_viewport_limits() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "attractor",
            "--name",
            "X",
            "--description",
            "d",
            "--positive-state",
            "ok",
            "--negative-state",
            "bad",
        ],
    );
    run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "t",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "none",
            "--components",
            "auth",
        ],
    );
    let out = run(&dir, &["matrix", "show"]);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        stderr.contains("sticky") || stderr.contains("--csv"),
        "expected viewport note on stderr, got: {stderr}"
    );
}

#[test]
fn verify_links_catches_attractor_missing_dual_pressure() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    std::fs::write(
        dir.path().join("residual/attractors.csv"),
        "id,name,description,positive_state,negative_state\nA-01,Clarity,desc,coherent,\n",
    )
    .unwrap();
    let out = run(&dir, &["verify", "links"]);
    assert!(!out.status.success());
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("negative_state"),
        "expected dual-pressure violation, got:\n{stdout}"
    );
}

#[test]
fn stressor_walk_context_warns_without_stakeholder_and_direct_user() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    run(
        &dir,
        &[
            "add",
            "persona",
            "--name",
            "solo",
            "--role",
            "Engineer",
            "--concerns",
            "n",
        ],
    );
    run(
        &dir,
        &[
            "add",
            "persona",
            "--name",
            "other",
            "--role",
            "Reviewer",
            "--concerns",
            "n",
        ],
    );
    let out = run(&dir, &["skill-data", "stressor-walk"]);
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("stakeholder") && stdout.contains("direct"),
        "expected persona role warning, got:\n{stdout}"
    );
}

